extra_css:
/* Light Well surfaces: board-formed architectural concrete slabs with tie-rod recesses and a razor edge of warm sunlight;
   hover widens the golden light graze across the top bevel. Headings look cast and side-lit in warm travertine gold.
   Scoped to own surfaces only. */
html[data-atmo="lightwell"] .card, html[data-atmo="lightwell"] .panel, html[data-atmo="lightwell"] .gx-card {
  background: linear-gradient(125deg, rgba(236,196,104,.09) 0%, transparent 48%), linear-gradient(180deg, rgba(30,30,34,.90), rgba(10,10,11,.95));
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  box-shadow: inset 0 1px 0 rgba(247,223,158,.32), inset 0 0 0 1px rgba(236,196,104,.20), 0 18px 46px rgba(0,0,0,.78);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="lightwell"] .card:hover, html[data-atmo="lightwell"] .gx-card:hover {
  transform: translateY(-2px);
  background: linear-gradient(125deg, rgba(247,223,158,.15) 0%, transparent 55%), linear-gradient(180deg, rgba(36,36,40,.92), rgba(12,12,14,.96));
  box-shadow: inset 0 1px 0 rgba(255,238,186,.55), inset 0 0 0 1px rgba(236,196,104,.46), 0 0 26px rgba(236,196,104,.12), 0 22px 54px rgba(0,0,0,.82); }
html[data-atmo="lightwell"] h1, html[data-atmo="lightwell"] h2 { background: linear-gradient(180deg, #fffdf7, #e6dcc8 50%, #9e9686); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="lightwell"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

